steps.solution:
#include <stdlib.h>

int **make_grid(int rows, int cols) {
    int **g = malloc(rows * sizeof *g);
    if (g == NULL) return NULL;
    for (int r = 0; r < rows; r++) {
        g[r] = calloc(cols, sizeof *g[r]);
        if (g[r] == NULL) {
            for (int k = 0; k < r; k++) free(g[k]);
            free(g);
            return NULL;
        }
    }
    return g;
}

void free_grid(int **g, int rows) {
    if (g == NULL) return;
    for (int r = 0; r < rows; r++) free(g[r]);
    free(g);
}

