steps.solution:
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *buf;
    size_t len;
    size_t cap;
} Builder;

int sb_init(Builder *b) {
    b->cap = 8;
    b->len = 0;
    b->buf = malloc(b->cap);
    if (b->buf == NULL) return -1;
    b->buf[0] = '\0';
    return 0;
}

int sb_append(Builder *b, const char *s) {
    size_t add = strlen(s);
    size_t need = b->len + add + 1;
    if (need > b->cap) {
        size_t cap = b->cap;
        while (cap < need) cap *= 2;
        char *tmp = realloc(b->buf, cap);
        if (tmp == NULL) return -1;
        b->buf = tmp;
        b->cap = cap;
    }
    memcpy(b->buf + b->len, s, add + 1);
    b->len += add;
    return 0;
}

const char *sb_str(const Builder *b) {
    return b->buf;
}

void sb_free(Builder *b) {
    free(b->buf);
    b->buf = NULL;
    b->len = 0;
    b->cap = 0;
}

steps.harness:
int main(void) {
    Builder b;
    CHECK_INT("sb_init succeeds", sb_init(&b), 0);
    CHECK_STR("starts empty", sb_str(&b), "");
    sb_append(&b, "rush");
    sb_append(&b, " ");
    sb_append(&b, "b");
    CHECK_STR("three appends", sb_str(&b), "rush b");
    CHECK_INT("len tracks characters", (int)b.len, 6);
    sb_append(&b, ", no stop, go go go, everybody rush");
    CHECK_STR("long append grows the buffer", sb_str(&b), "rush b, no stop, go go go, everybody rush");
    CHECK("cap is big enough", b.cap > b.len);
    sb_free(&b);
    CHECK("sb_free resets buf", b.buf == NULL && b.len == 0 && b.cap == 0);
    Builder many;
    sb_init(&many);
    for (int i = 0; i < 1000; i++) sb_append(&many, "ab");
    CHECK_INT("1000 appends", (int)strlen(sb_str(&many)), 2000);
    CHECK_INT("len after 1000 appends", (int)many.len, 2000);
    sb_free(&many);
    return 0;
}

steps.text:
This module puts structs, pointers and `malloc` together to build the first real **data structure**. Arrays store elements side by side, which makes them fast to index but hard to grow or insert into. A **linked list** takes the opposite approach: each element (a **node**) is separate, and each node holds a pointer to the next one.

```c
struct Node {
    int value;
    struct Node *next;
};
```

- `value` is the data.
- `next` points at the following node, or is `NULL` for the last node.
- The whole list is reached through one pointer to the first node, called the **head**. An empty list is just `head == NULL`.

A struct can't contain itself (that would be infinitely big), but it can contain a **pointer** to its own type, because a pointer is a fixed size.

### Walking a list

You can't jump to "element 5" of a list. You start at the head and follow `next` pointers until you reach `NULL`:

```c
#include <stdio.h>
#include <stddef.h>

struct Node {
    const char *name;
    struct Node *next;
};

int main(void) {
    struct Node third = {"cherry", NULL};
    struct Node second = {"banana", &third};
    struct Node first = {"apple", &second};
    int count = 0;
    for (struct Node *p = &first; p != NULL; p = p->next) {
        printf("%s\n", p->name);
        count++;
    }
    printf("%d nodes\n", count);
    return 0;
}
```

```text
apple
banana
cherry
3 nodes
```

The `for` loop is the standard list traversal: start at the head, stop at `NULL`, and step with `p = p->next`. You'll write it many times.

In real programs nodes are allocated with `malloc` (next step); here they're plain local variables to keep the first example simple.

