steps.solution:
typedef struct {
    int items[64];
    int top;
} Stack;

int push(Stack *s, int v) {
    if (s->top == 64) return 0;
    s->items[s->top++] = v;
    return 1;
}

int pop(Stack *s) {
    return s->items[--s->top];
}

