    CHECK_INT("count_bits(7)", count_bits(7), 3);
    CHECK_INT("count_bits(8)", count_bits(8), 1);
    CHECK_INT("count_bits(255)", count_bits(255), 8);
    CHECK_INT("count_bits(0xFFFFFFFF)", count_bits(0xFFFFFFFFu), 32);
    return 0;
}

