steps.solution:
#include <stdio.h>

int format_kd(char *buf, size_t size, const char *name, int kills, int deaths) {
    int needed = snprintf(buf, size, "%s %d/%d", name, kills, deaths);
    if (needed < 0 || (size_t)needed >= size) return -1;
    return 0;
}

