}

steps.solution:
#include <stddef.h>

const void *find_first(const void *base, size_t n, size_t size, int (*pred)(const void *)) {
    const char *bytes = base;
    for (size_t i = 0; i < n; i++) {
        const void *elem = bytes + i * size;
        if (pred(elem)) return elem;
    }
    return NULL;
}

