    CHECK_INT("2 + 3 result", r, 5);
    r = 42;
    CHECK_INT("INT_MAX + 1 overflows", checked_add(INT_MAX, 1, &r), 0);
    CHECK_INT("out untouched on overflow", r, 42);
    CHECK_INT("INT_MIN + -1 overflows", checked_add(INT_MIN, -1, &r), 0);
    CHECK_INT("INT_MAX + INT_MIN fits", checked_add(INT_MAX, INT_MIN, &r), 1);
