steps.solution:
class Wallet {
public:
    int money() const { return money_; }
    bool buy(int price) {
        if (price > money_) return false;
        money_ -= price;
        return true;
    }
    void earn(int amount) {
        money_ += amount;
        if (money_ > 16000) money_ = 16000;
    }

private:
    int money_ = 800;
};

