steps.solution:
#include <algorithm>

class Health {
public:
    explicit Health(int max) : max_(std::max(1, max)), hp_(max_) {}
    void damage(int n) {
        if (n > 0) hp_ = std::max(0, hp_ - n);
    }
    void heal(int n) {
        if (n > 0) hp_ = std::min(max_, hp_ + n);
    }
    int hp() const { return hp_; }
    int max() const { return max_; }
    bool alive() const { return hp_ > 0; }

private:
    int max_;
    int hp_;
};

