steps.solution:
#include <algorithm>

class IntArray {
public:
    explicit IntArray(int n) : data_(new int[n]()), n_(n) {}
    ~IntArray() { delete[] data_; }
    // copy constructor goes here
    IntArray(const IntArray& other) : data_(new int[other.n_]), n_(other.n_) {
        for (int i = 0; i < n_; i++) data_[i] = other.data_[i];
    }
    IntArray& operator=(IntArray other) {
        std::swap(data_, other.data_);
        std::swap(n_, other.n_);
        return *this;
    }
    int size() const { return n_; }
    int& at(int i) { return data_[i]; }
    const int* raw() const { return data_; }

private:
    int* data_;
    int n_;
};

