int main() {
    std::vector<int> scores = {16, 9, 22, 13, 30};
    std::[[sort]](scores.begin(), scores.end());
    std::[[reverse]](scores.[[begin()]], scores.end());
    for (int s : scores) std::cout << s << " ";
    std::cout << "\n";
