int main() {
    std::vector<std::string> maps = {"inferno", "nuke", "overpass", "dust2"};
    std::sort(maps.begin(), maps.end(), [](const std::string& a, const std::string& b) {
        [[return]] a.[[size()]] [[<]] b.size();
    });
    for (const auto& m : maps) std::cout << m << " ";
    std::cout << "\n";
}

steps.solution:
#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

