#include <algorithm>
#include <string>
#include <vector>

int count_headshots(const std::vector<std::string>& kills) {
    return (int)std::count_if(kills.begin(), kills.end(), [](const std::string& k) {
        return k.size() >= 3 && k.substr(k.size() - 3) == "_hs";
    });
}

