steps.solution:
#include <map>
#include <string>

int remove_expired(std::map<std::string, int>& sessions, int now) {
    int removed = 0;
    for (auto it = sessions.begin(); it != sessions.end();) {
        if (it->second <= now) {
            it = sessions.erase(it);
            removed++;
        } else {
            ++it;
        }
    }
    return removed;
}

