steps.solution:
#include <algorithm>
#include <functional>
#include <string>
#include <vector>

class EventBus {
public:
    int on(const std::string& event, std::function<void(const std::string&)> fn) {
        handlers_.push_back({++last_id_, event, fn});
        return last_id_;
    }
    bool off(int id) {
        auto it = std::find_if(handlers_.begin(), handlers_.end(), [id](const Handler& h) { return h.id == id; });
        if (it == handlers_.end()) return false;
        handlers_.erase(it);
        return true;
    }
    int emit(const std::string& event, const std::string& payload) {
        int ran = 0;
        for (const auto& h : handlers_) {
            if (h.event == event) {
                h.fn(payload);
                ran++;
            }
        }
        return ran;
    }

private:
    struct Handler {
        int id;
        std::string event;
        std::function<void(const std::string&)> fn;
    };
    std::vector<Handler> handlers_;
    int last_id_ = 0;
};

steps.harness:
int main() {
    EventBus bus;
    std::string log;
    int kills = 0;
    int a = bus.on("kill", [&](const std::string& who) { log += "A:" + who + " "; kills++; });
    int b = bus.on("kill", [&](const std::string& who) { log += "B:" + who + " "; });
    bus.on("bomb", [&](const std::string& site) { log += "bomb@" + site + " "; });
    CHECK("ids are unique", a != b);
    CHECK_EQ("two kill handlers ran", bus.emit("kill", "ropz"), 2);
    CHECK_EQ("bomb handler", bus.emit("bomb", "B"), 1);
    CHECK_EQ("no handlers", bus.emit("defuse", "x"), 0);
    CHECK_EQ("order", log, std::string("A:ropz B:ropz bomb@B "));
    CHECK_EQ("off works", bus.off(a), true);
    CHECK_EQ("off twice fails", bus.off(a), false);
    bus.emit("kill", "rain");
    CHECK_EQ("A no longer runs", kills, 1);
    CHECK_EQ("B still runs", log, std::string("A:ropz B:ropz bomb@B B:rain "));
}

steps.text:
In C, every `malloc` needs exactly one `free`, and forgetting it (or doing it twice) is a bug. C++'s raw `new` and `delete` have the same problem. A **smart pointer** is a small object that owns a heap object and deletes it for you in its destructor. It's RAII applied to heap memory.

`std::unique_ptr<T>` (from `<memory>`) is the one to use by default. It has one owner, and it costs nothing extra at run time compared with a raw pointer.

```cpp
#include <iostream>
#include <memory>
#include <string>
#include <utility>

struct Robot {
    std::string name;
    int battery;
    Robot(std::string n, int b) : name(n), battery(b) { std::cout << name << " built\n"; }
    ~Robot() { std::cout << name << " scrapped\n"; }
};

int main() {
    auto r = std::make_unique<Robot>("R2", 80);   // arguments go to Robot's constructor
    r->battery -= 30;                              // -> works like a raw pointer
    std::cout << (*r).name << " at " << r->battery << "%\n";
    {
        auto temp = std::make_unique<Robot>("C3", 100);
        std::cout << "inner block ends\n";
    }                                              // temp deletes its Robot here
    std::cout << "main ends\n";
}                                                  // r deletes its Robot here
```

```text
R2 built
R2 at 50%
C3 built
inner block ends
C3 scrapped
main ends
R2 scrapped
```

### How it works

- `std::make_unique<T>(args...)` allocates a `T` on the heap, passes `args` to its constructor, and returns a `unique_ptr<T>` owning it. It's the only line where the allocation happens, and there's never a matching `delete` in your code.
- `p->member` and `*p` work exactly like a raw pointer.
- When the `unique_ptr` goes out of scope, its destructor deletes the object. The output shows each robot scrapped at the end of its own block.
- `auto` saves writing `std::unique_ptr<Robot>` twice.

### Common mistakes

- Writing `std::unique_ptr<Robot> r(new Robot(...))`. It works, but `make_unique` is shorter and never leaks if something goes wrong in between.
- Creating a `unique_ptr` for something that could just be a normal local variable. Use the heap only when you need it: the object must outlive the scope, it's very large, or it's polymorphic.

