#include <memory>
#include <vector>

class Weapon {
public:
    virtual int damage(int hits) const = 0;
    virtual ~Weapon() = default;
};

class Pistol : public Weapon {
public:
    int damage(int hits) const override { return 25 * hits; }
};

class Shotgun : public Weapon {
public:
    int damage(int hits) const override {
        if (hits <= 0) return 0;
        return 80 + 20 * (hits - 1);
    }
};

int total_damage(const std::vector<std::unique_ptr<Weapon>>& ws, int hits) {
    int t = 0;
    for (const auto& w : ws) t += w->damage(hits);
    return t;
}

