template <typename Pred, typename... Ts>
int count_if_all(Pred pred, Ts... xs) {
    return (0 + ... + (pred(xs) ? 1 : 0));
}

template <typename... Ts>
bool all_positive(Ts... xs) {
    return ((xs > 0) && ...);
}

