#include <array>
#include <cstddef>
#include <cstdint>
#include <string_view>

template <std::size_t N>
constexpr std::array<int, N> first_primes() {
    std::array<int, N> out{};
    std::size_t found = 0;
    for (int n = 2; found < N; n++) {
        bool prime = true;
        for (int d = 2; d * d <= n; d++) {
            if (n % d == 0) {
                prime = false;
                break;
            }
        }
        if (prime) out[found++] = n;
    }
    return out;
}

constexpr std::uint32_t hash32(std::string_view s) {
    std::uint32_t h = 2166136261u;
    for (char c : s) {
        h ^= static_cast<unsigned char>(c);
        h *= 16777619u;
    }
    return h;
}

steps.harness:
