steps.solution:
#include <chrono>
#include <format>
#include <string>

std::string mmss(std::chrono::milliseconds t) {
    auto m = std::chrono::duration_cast<std::chrono::minutes>(t);
    auto s = std::chrono::duration_cast<std::chrono::seconds>(t - m);
    return std::format("{}:{:02}", m.count(), s.count());
}

