steps.solution:
#include <functional>
#include <vector>

using Discount = std::function<long(long)>;

Discount percent_off(int pct) {
    return [pct](long cents) { return cents - cents * pct / 100; };
}

Discount flat_off(long amount) {
    return [amount](long cents) { return cents > amount ? cents - amount : 0; };
}

struct Cart {
    std::vector<long> prices;
    Discount discount = [](long cents) { return cents; };
    long total() const;
};

long Cart::total() const {
    long sum = 0;
    for (long p : prices) sum += p;
    return discount(sum);
}

steps.harness:
int main() {
    Cart c;
    c.prices = {2700, 1000, 300};
    CHECK_EQ("no discount", c.total(), 4000L);
    c.discount = percent_off(25);
    CHECK_EQ("25% off", c.total(), 3000L);
    c.discount = flat_off(500);
    CHECK_EQ("flat 500 off", c.total(), 3500L);
    c.discount = flat_off(9999);
    CHECK_EQ("never below 0", c.total(), 0L);
    auto ten = percent_off(10), half = percent_off(50);
    CHECK("each closure keeps its own pct", ten(1000) == 900 && half(1000) == 500);
}

steps.text:
A **factory** creates objects by **name**: the name comes from a config file, a network message or a command line, and the result is returned through a base-class pointer. The naive version is a giant `if`/`else` chain that must be edited for every new type. Large codebases use a **registry** instead: a map from name to a **creator function**. Adding a type means registering one more entry, and the factory itself never changes.

```cpp
#include <functional>
#include <iostream>
#include <map>
#include <memory>
#include <string>

struct Codec {
    virtual ~Codec() = default;
    virtual std::string encode(const std::string& s) const = 0;
};

struct Upper : Codec {
    std::string encode(const std::string& s) const override {
        std::string r = s;
        for (char& c : r) if (c >= 'a' && c <= 'z') c = char(c - 32);
        return r;
    }
};

struct Reverse : Codec {
    std::string encode(const std::string& s) const override { return {s.rbegin(), s.rend()}; }
};

int main() {
    std::map<std::string, std::function<std::unique_ptr<Codec>()>> registry;
    registry["upper"] = [] { return std::make_unique<Upper>(); };
    registry["reverse"] = [] { return std::make_unique<Reverse>(); };

    for (const char* name : {"reverse", "rot13", "upper"}) {
        auto it = registry.find(name);
        if (it == registry.end()) {
            std::cout << name << ": unknown codec\n";
            continue;
        }
        std::unique_ptr<Codec> c = it->second();       // call the creator
        std::cout << name << ": " << c->encode("hello") << "\n";
    }
}
```

```text
reverse: olleh
rot13: unknown codec
upper: HELLO
```

### How it works

- Each map value is a function that takes nothing and returns a `std::unique_ptr<Codec>`. A capture-less lambda `[] { return std::make_unique<Upper>(); }` fits, because `unique_ptr<Upper>` converts to `unique_ptr<Codec>`.
- `it->second()` calls the stored creator and gets a brand new object. The caller owns it, which the `unique_ptr` return type makes obvious.
- Unknown names are looked up with `find`, never `[]`, which would insert an empty function.

### Your task

- `add`: if `creators_` already contains the name, return `false`; otherwise store it (move the `std::function` in) and return `true`.
- `create`: `find` the name; return `nullptr` if missing, otherwise call the creator.
- `names`: a `std::map` is already sorted by key, so loop over it and collect the keys.

**Your turn:** implement `Factory::add` (returns false if the name is already registered), `Factory::create` (returns `nullptr` for unknown names) and `Factory::names` (sorted).

