steps.solution:
#include <unordered_set>
#include <vector>

bool has_duplicate(const std::vector<int>& v) {
    std::unordered_set<int> seen;
    seen.reserve(v.size());
    for (int x : v) {
        if (!seen.insert(x).second) return true;
    }
    return false;
}

