    CHECK_EQ("small without", has_duplicate({3, 1, 4, 5}), false);
    CHECK_EQ("empty", has_duplicate({}), false);
    std::vector<int> big(200000);
    for (int i = 0; i < 200000; i++) big[i] = i * 7;
    CHECK_EQ("200,000 distinct values", has_duplicate(big), false);
    big.push_back(7 * 199999);
    CHECK_EQ("duplicate at the very end", has_duplicate(big), true);
