steps.solution:
#include <algorithm>
#include <vector>

long count_in_range(const std::vector<int>& sorted, int lo, int hi) {
    if (lo > hi) return 0;
    auto first = std::lower_bound(sorted.begin(), sorted.end(), lo);
    auto last = std::upper_bound(sorted.begin(), sorted.end(), hi);
    return last - first;
}

steps.harness:
