    CHECK_EQ("exactly 3", count_in_range(v, 3, 3), 3L);
    CHECK_EQ("between values", count_in_range(v, 9, 12), 0L);
    CHECK_EQ("everything", count_in_range(v, -100, 100), 8L);
    CHECK_EQ("lo > hi", count_in_range(v, 8, 3), 0L);
