steps.solution:
#include <utility>
#include <vector>

int partition(std::vector<int>& v, int lo, int hi) {
    int pivot = v[hi];
    int i = lo;
    for (int j = lo; j < hi; j++) {
        if (v[j] < pivot) {
            std::swap(v[i], v[j]);
            i++;
        }
    }
    std::swap(v[i], v[hi]);
    return i;
}

void quick_sort(std::vector<int>& v, int lo, int hi) {
    if (lo >= hi) return;
    int p = partition(v, lo, hi);
    quick_sort(v, lo, p - 1);
    quick_sort(v, p + 1, hi);
}

