}

steps.solution:
#include <utility>
#include <vector>

int kth_smallest(std::vector<int> v, int k) {
    int lo = 0, hi = static_cast<int>(v.size()) - 1;
    while (true) {
        if (lo == hi) return v[lo];
        int mid = lo + (hi - lo) / 2;
        std::swap(v[mid], v[hi]);
        int pivot = v[hi], i = lo;
        for (int j = lo; j < hi; j++) {
            if (v[j] < pivot) std::swap(v[i++], v[j]);
        }
        std::swap(v[i], v[hi]);
        if (k == i) return v[i];
        if (k < i) hi = i - 1;
        else lo = i + 1;
    }
}

steps.harness:
int main() {
    CHECK_EQ("median of 5", kth_smallest({9, 1, 7, 3, 5}, 2), 5);
    CHECK_EQ("smallest", kth_smallest({9, 1, 7, 3, 5}, 0), 1);
    CHECK_EQ("largest", kth_smallest({9, 1, 7, 3, 5}, 4), 9);
    CHECK_EQ("duplicates", kth_smallest({4, 4, 4, 1}, 2), 4);
    CHECK_EQ("single", kth_smallest({42}, 0), 42);
    std::vector<int> sorted(200000);
    for (int i = 0; i < 200000; i++) sorted[i] = i;
    CHECK_EQ("already sorted input stays fast", kth_smallest(sorted, 123456), 123456);
    std::vector<int> big(300000);
    for (int i = 0; i < 300000; i++) big[i] = static_cast<int>((7919LL * i) % 300000);
    CHECK_EQ("300,000 shuffled", kth_smallest(big, 150000), 150000);
}

