steps.solution:
#include <algorithm>
#include <functional>
#include <list>
#include <vector>

class IntSet {
public:
    bool insert(int key);
    bool contains(int key) const;
    std::size_t size() const { return size_; }

private:
    std::size_t bucket_of(int key) const { return std::hash<int>{}(key) % buckets_.size(); }
    std::vector<std::list<int>> buckets_ = std::vector<std::list<int>>(16);
    std::size_t size_ = 0;
};

bool IntSet::insert(int key) {
    auto& b = buckets_[bucket_of(key)];
    if (std::find(b.begin(), b.end(), key) != b.end()) return false;
    b.push_back(key);
    size_++;
    return true;
}

bool IntSet::contains(int key) const {
    const auto& b = buckets_[bucket_of(key)];
    return std::find(b.begin(), b.end(), key) != b.end();
}

steps.harness:
