    CHECK_EQ("insert 21 (same bucket as 5)", s.insert(21), true);
    CHECK_EQ("insert 5 again", s.insert(5), false);
    CHECK_EQ("contains 21", s.contains(21), true);
    CHECK_EQ("does not contain 37", s.contains(37), false);
    CHECK_EQ("negative keys", s.insert(-3) && s.contains(-3), true);
    CHECK_EQ("size", s.size(), 3u);
    for (int i = 0; i < 1000; i++) s.insert(i);
