#include <optional>
#include <unordered_map>
#include <utility>

class LruCache {
public:
    explicit LruCache(std::size_t capacity) : capacity_(capacity) {}
    std::optional<int> get(int key);
    void put(int key, int value);
    std::size_t size() const { return items_.size(); }

private:
    std::size_t capacity_;
    std::list<std::pair<int, int>> items_;
    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> where_;
};

steps.solution:
#include <list>
#include <optional>
#include <unordered_map>
#include <utility>

class LruCache {
public:
    explicit LruCache(std::size_t capacity) : capacity_(capacity) {}
    std::optional<int> get(int key);
    void put(int key, int value);
    std::size_t size() const { return items_.size(); }

private:
    std::size_t capacity_;
    std::list<std::pair<int, int>> items_;
    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> where_;
};

std::optional<int> LruCache::get(int key) {
    auto it = where_.find(key);
    if (it == where_.end()) return std::nullopt;
    items_.splice(items_.begin(), items_, it->second);
    return it->second->second;
}

void LruCache::put(int key, int value) {
    auto it = where_.find(key);
    if (it != where_.end()) {
        it->second->second = value;
        items_.splice(items_.begin(), items_, it->second);
        return;
    }
    items_.emplace_front(key, value);
    where_[key] = items_.begin();
    if (items_.size() > capacity_) {
        where_.erase(items_.back().first);
        items_.pop_back();
    }
}

steps.harness:
int main() {
    LruCache c(2);
    c.put(1, 100);
    c.put(2, 200);
    CHECK_EQ("get 1", c.get(1).value_or(-1), 100);
    c.put(3, 300);
    CHECK("2 was least recent, evicted", !c.get(2));
    CHECK_EQ("1 survived", c.get(1).value_or(-1), 100);
    CHECK_EQ("3 present", c.get(3).value_or(-1), 300);
    c.put(1, 111);
    CHECK_EQ("update keeps size", c.size(), 2u);
    c.put(4, 400);
    CHECK("3 evicted after 1 was refreshed", !c.get(3));
    CHECK_EQ("updated value", c.get(1).value_or(-1), 111);
    LruCache big(1000);
    long long sum = 0;
    for (int i = 0; i < 300000; i++) {
        big.put(i % 1500, i);
        sum += big.get(i % 700).value_or(0);
    }
    CHECK("300,000 operations", sum > 0 && big.size() == 1000);
}

steps.text:
Lists and arrays are **linear**: each element has one next element. A **tree** branches: each node can have several children, and every node except the top one (the **root**) has exactly one parent. File systems, HTML pages, company org charts and the `std::map` you've been using are all trees.

In a **binary tree**, each node has at most two children, called `left` and `right`. Ownership is naturally a tree too, so `std::unique_ptr` children mean the whole tree frees itself when the root goes away:

```cpp
struct Node {
    int value;
    std::unique_ptr<Node> left, right;
};
```

### Thinking recursively

A tree is either **empty**, or a node whose left and right children are **smaller trees**. So almost every tree algorithm has the same shape:

1. Handle the empty tree (`nullptr`). This is the base case.
2. Ask the same question of the left and right subtrees.
3. Combine their answers with the current node.

```cpp
#include <algorithm>
#include <iostream>
#include <memory>

struct Node {
    int value;
    std::unique_ptr<Node> left, right;
};

std::unique_ptr<Node> leaf(int v) { return std::make_unique<Node>(Node{v, nullptr, nullptr}); }

int count(const Node* n) {
    if (!n) return 0;                                         // empty tree
    return 1 + count(n->left.get()) + count(n->right.get());  // me + both sides
}

int max_value(const Node* n) {
    int best = n->value;                                      // assumes n isn't null
    if (n->left) best = std::max(best, max_value(n->left.get()));
    if (n->right) best = std::max(best, max_value(n->right.get()));
    return best;
}

int main() {
    /*        4
             / \
            9   2
               /
              7        */
    auto root = leaf(4);
    root->left = leaf(9);
    root->right = leaf(2);
    root->right->left = leaf(7);
    std::cout << count(root.get()) << " nodes, max " << max_value(root.get()) << "\n";
}
```

```text
4 nodes, max 9
```

### How it works

- `count(nullptr)` is 0. For a real node, it's 1 (the node itself) plus the counts of both subtrees. Trust the recursion: you don't need to trace every call to know it's right.
- `.get()` turns a `unique_ptr` into a plain `const Node*` for reading. Functions that only look at a tree take raw pointers; ownership stays with the `unique_ptr`s.

### Your task

- **height**: an empty tree has height 0. A node's height is 1 plus the **larger** of its two subtrees' heights (`std::max` from `<algorithm>`).
- **sum**: like `count`, but add `n->value` instead of 1. Return `long` so big trees don't overflow.

**Your turn:** write `height` (an empty tree has height 0, a single node 1) and `sum`.

