int height(const Node* n) {
    if (!n) return 0;
    return 1 + std::max(height(n->left.get()), height(n->right.get()));
}

long sum(const Node* n) {
    if (!n) return 0;
    return n->value + sum(n->left.get()) + sum(n->right.get());
}

