#include <climits>
#include <memory>
#include <vector>

struct Node {
    int key;
    std::unique_ptr<Node> left, right;
};

void in_order(const Node* n, std::vector<int>& out) {
    if (!n) return;
    in_order(n->left.get(), out);
    out.push_back(n->key);
    in_order(n->right.get(), out);
}

bool is_bst(const Node* n, long lo, long hi) {
    if (!n) return true;
    if (n->key <= lo || n->key >= hi) return false;
    return is_bst(n->left.get(), lo, n->key) && is_bst(n->right.get(), n->key, hi);
}

