    in_order(good.get(), v);
    CHECK_EQ("in-order is sorted", v, (std::vector<int>{1, 3, 6, 8, 10}));
    CHECK_EQ("valid BST", is_bst(good.get(), LONG_MIN, LONG_MAX), true);
