steps.solution:
#include <array>
#include <memory>
#include <string>
#include <vector>

class Trie {
public:
    void insert(const std::string& w);
    bool contains(const std::string& w) const;
    int count_prefix(const std::string& p) const;
    std::vector<std::string> complete(const std::string& p, std::size_t limit) const;

private:
    struct Node {
        std::array<std::unique_ptr<Node>, 26> next;
        bool end = false;
        int pass = 0;
    };
    const Node* find(const std::string& p) const {
        const Node* n = &root_;
        for (char c : p) {
            n = n->next[c - 'a'].get();
            if (!n) return nullptr;
        }
        return n;
    }
    static void collect(const Node* n, std::string& word, std::size_t limit, std::vector<std::string>& out) {
        if (out.size() >= limit) return;
        if (n->end) out.push_back(word);
        for (int i = 0; i < 26; i++) {
            if (n->next[i]) {
                word.push_back(static_cast<char>('a' + i));
                collect(n->next[i].get(), word, limit, out);
                word.pop_back();
            }
        }
    }
    Node root_;
};

void Trie::insert(const std::string& w) {
    if (contains(w)) return;
    Node* n = &root_;
    n->pass++;
    for (char c : w) {
        auto& child = n->next[c - 'a'];
        if (!child) child = std::make_unique<Node>();
        n = child.get();
        n->pass++;
    }
    n->end = true;
}

bool Trie::contains(const std::string& w) const {
    const Node* n = find(w);
    return n && n->end;
}

int Trie::count_prefix(const std::string& p) const {
    const Node* n = find(p);
    return n ? n->pass : 0;
}

std::vector<std::string> Trie::complete(const std::string& p, std::size_t limit) const {
    std::vector<std::string> out;
    const Node* n = find(p);
    if (!n) return out;
    std::string word = p;
    collect(n, word, limit, out);
    return out;
}

