    t.insert("dust");
    CHECK_EQ("contains dust", t.contains("dust"), true);
    CHECK_EQ("prefix only is not a word", t.contains("du"), false);
    CHECK_EQ("words starting with du", t.count_prefix("du"), 3);
    CHECK_EQ("words starting with nuke", t.count_prefix("nuke"), 2);
    CHECK_EQ("no words with x", t.count_prefix("x"), 0);
    CHECK_EQ("empty prefix counts all (duplicate once)", t.count_prefix(""), 7);
    CHECK_EQ("complete du", t.complete("du", 10), (std::vector<std::string>{"dune", "dust", "dustii"}));
    CHECK_EQ("limit", t.complete("", 2), (std::vector<std::string>{"ancient", "dune"}));
    CHECK("no completions", t.complete("zz", 5).empty());
