int unique_count(const char* text, int count) {
    int result = -1;
    int* unique = nullptr;
    int* values = static_cast<int*>(xmalloc(sizeof(int) * count));
    const char* p = text;
    for (int i = 0; i < count; i++) {
        char* end;
        long v = std::strtol(p, &end, 10);
        if (end == p) goto cleanup;
        values[i] = static_cast<int>(v);
        p = end;
    }
    unique = static_cast<int*>(xmalloc(sizeof(int) * count));
    {
        int n = 0;
        for (int i = 0; i < count; i++) {
            bool seen = false;
            for (int j = 0; j < n; j++) seen = seen || unique[j] == values[i];
            if (!seen) unique[n++] = values[i];
