void apply_bans(std::vector<std::string>& roster, const std::set<std::string>& banned, const std::string& sub) {
    int removed = 0;
    for (std::size_t i = 0; i < roster.size(); i++) {
        if (banned.count(roster[i])) {
            roster.erase(roster.begin() + i);
