#include <vector>

int win_rate(int wins, int games) {
    if (games <= 0) return 0;
    return static_cast<int>(static_cast<long long>(wins) * 100 / games);
}

double average(const std::vector<int>& scores) {
    if (scores.empty()) return 0.0;
    long long sum = 0;
    for (int s : scores) sum += s;
    return static_cast<double>(sum) / static_cast<double>(scores.size());
}

long long last_n_total(const std::vector<int>& scores, std::size_t n) {
    long long total = 0;
    std::size_t start = n >= scores.size() ? 0 : scores.size() - n;
    for (std::size_t i = start; i < scores.size(); i++) total += scores[i];
    return total;
}

