#include <stdlib.h>

typedef struct {
    int *data;
    int size;
    int cap;
} IntVec;

IntVec vec_new(void) {
    IntVec v;
    v.cap = 4;
    v.size = 0;
    v.data = malloc(v.cap * sizeof(int));
    return v;
}

void vec_push(IntVec *v, int x) {
    if (v->size == v->cap) {
        int *bigger = realloc(v->data, 2 * v->cap * sizeof(int));
        if (bigger == NULL) return; // out of memory: leave v as it was
        v->data = bigger;
        v->cap *= 2;
    }
    v->data[v->size++] = x;
}

int vec_get(const IntVec *v, int i) {
    return v->data[i];
}

void vec_free(IntVec *v) {
    free(v->data);
    v->data = NULL;
    v->size = 0;
    v->cap = 0;
}

