#include <ostream>
#include <vector>

class Matrix {
public:
    Matrix(int rows, int cols) : rows_(rows), cols_(cols), data_(rows * cols, 0.0) {}
    int rows() const { return rows_; }
    int cols() const { return cols_; }
    double& at(int r, int c) { return data_[r * cols_ + c]; }
    double at(int r, int c) const { return data_[r * cols_ + c]; }
    static Matrix identity(int n) {
        Matrix m(n, n);
        for (int i = 0; i < n; i++) m.at(i, i) = 1;
        return m;
    }
    Matrix transpose() const {
        Matrix t(cols_, rows_);
        for (int r = 0; r < rows_; r++)
            for (int c = 0; c < cols_; c++) t.at(c, r) = at(r, c);
        return t;
    }
    double determinant() const {
        if (rows_ == 1) return at(0, 0);
        double det = 0;
        for (int c = 0; c < cols_; c++) {
            Matrix minor(rows_ - 1, cols_ - 1);
            for (int r = 1; r < rows_; r++) {
                int mc = 0;
                for (int k = 0; k < cols_; k++) {
                    if (k == c) continue;
                    minor.at(r - 1, mc++) = at(r, k);
                }
            }
            double sign = (c % 2 == 0) ? 1.0 : -1.0;
            det += sign * at(0, c) * minor.determinant();
        }
        return det;
    }

private:
    int rows_ = 0, cols_ = 0;
    std::vector<double> data_;
};

Matrix operator+(const Matrix& a, const Matrix& b) {
    Matrix out(a.rows(), a.cols());
    for (int r = 0; r < a.rows(); r++)
        for (int c = 0; c < a.cols(); c++) out.at(r, c) = a.at(r, c) + b.at(r, c);
    return out;
}

bool operator==(const Matrix& a, const Matrix& b) {
    if (a.rows() != b.rows() || a.cols() != b.cols()) return false;
    for (int r = 0; r < a.rows(); r++)
        for (int c = 0; c < a.cols(); c++)
            if (a.at(r, c) != b.at(r, c)) return false;
    return true;
}

Matrix operator*(const Matrix& m, double k) {
    Matrix out(m.rows(), m.cols());
    for (int r = 0; r < m.rows(); r++)
        for (int c = 0; c < m.cols(); c++) out.at(r, c) = m.at(r, c) * k;
    return out;
}

Matrix operator*(const Matrix& a, const Matrix& b) {
    Matrix out(a.rows(), b.cols());
    for (int r = 0; r < a.rows(); r++)
        for (int c = 0; c < b.cols(); c++) {
            double s = 0;
            for (int k = 0; k < a.cols(); k++) s += a.at(r, k) * b.at(k, c);
            out.at(r, c) = s;
        }
    return out;
}

std::ostream& operator<<(std::ostream& os, const Matrix& m) {
    for (int r = 0; r < m.rows(); r++) {
        for (int c = 0; c < m.cols(); c++) {
            if (c) os << ' ';
            os << m.at(r, c);
        }
        os << '\n';
    }
    return os;
}

