#include <algorithm>
#include <iostream>
#include <map>
#include <memory>
#include <string>
#include <vector>

struct ShopEntry {
    int price;
    std::string kind;
};

const std::map<std::string, ShopEntry> shop = {
    {"ak47", {2700, "primary"}},
    {"awp", {4750, "primary"}},
    {"deagle", {700, "secondary"}},
    {"flash", {200, "grenade"}},
    {"smoke", {300, "grenade"}},
    {"kevlar", {650, "gear"}},
};

class Item {
public:
    Item(std::string name, int price) : name_(std::move(name)), price_(price) {}
    virtual ~Item() = default;
    std::string name() const { return name_; }
    int price() const { return price_; }
    virtual int slot() const = 0;

private:
    std::string name_;
    int price_;
};

class Primary : public Item {
public:
    using Item::Item;
    int slot() const override { return 1; }
};
class Secondary : public Item {
public:
    using Item::Item;
    int slot() const override { return 2; }
};
class Grenade : public Item {
public:
    using Item::Item;
    int slot() const override { return 4; }
};
class Gear : public Item {
public:
    using Item::Item;
    int slot() const override { return 5; }
};

std::unique_ptr<Item> make_item(const std::string& name) {
    const ShopEntry& e = shop.at(name);
    if (e.kind == "primary") return std::make_unique<Primary>(name, e.price);
    if (e.kind == "secondary") return std::make_unique<Secondary>(name, e.price);
    if (e.kind == "grenade") return std::make_unique<Grenade>(name, e.price);
    return std::make_unique<Gear>(name, e.price);
}

std::string rule_problem(const std::vector<std::unique_ptr<Item>>& inv, const Item& want) {
    int same_slot = 0, same_name = 0;
    for (const auto& it : inv) {
        if (it->slot() == want.slot()) same_slot++;
        if (it->name() == want.name()) same_name++;
    }
    if ((want.slot() == 1 || want.slot() == 2) && same_slot > 0) return "slot full";
    if (want.slot() == 4 && same_name >= 2) return "limit reached";
    if (want.slot() == 5 && same_name > 0) return "already have " + want.name();
    return "";
}

int main() {
    int money = 4000;
    std::vector<std::unique_ptr<Item>> inventory;
    std::string cmd;
    while (std::cin >> cmd) {
        if (cmd == "buy") {
            std::string name;
            std::cin >> name;
            auto it = shop.find(name);
            if (it == shop.end()) {
                std::cout << "unknown item\n";
                continue;
            }
            auto item = make_item(name);
            std::string problem = rule_problem(inventory, *item);
            if (!problem.empty()) {
                std::cout << problem << "\n";
            } else if (item->price() > money) {
                std::cout << "not enough money\n";
            } else {
                money -= item->price();
                inventory.push_back(std::move(item));
                std::cout << "bought " << name << "\n";
            }
        } else if (cmd == "sell") {
            std::string name;
            std::cin >> name;
            auto it = std::find_if(inventory.rbegin(), inventory.rend(), [&](const auto& p) { return p->name() == name; });
            if (it == inventory.rend()) {
                std::cout << "you don't have " << name << "\n";
            } else {
                money = std::min(16000, money + (*it)->price());
                inventory.erase(std::next(it).base());
                std::cout << "sold " << name << "\n";
            }
        } else if (cmd == "round") {
            std::string result;
            std::cin >> result;
            money = std::min(16000, money + (result == "win" ? 3250 : 1400));
            std::cout << "$" << money << "\n";
        } else if (cmd == "money") {
            std::cout << "$" << money << "\n";
        } else if (cmd == "list") {
            if (inventory.empty()) std::cout << "nothing\n";
            std::vector<const Item*> sorted;
            for (const auto& it : inventory) sorted.push_back(it.get());
            std::stable_sort(sorted.begin(), sorted.end(), [](const Item* a, const Item* b) { return a->slot() < b->slot(); });
            for (const Item* it : sorted) std::cout << it->slot() << " " << it->name() << "\n";
        }
    }
}

