}

exercise.solution:
struct Node {
    int v;
    struct Node *next;
};

int list_max(const struct Node *h) {
    int m = h->v;
    for (const struct Node *p = h->next; p; p = p->next)
        if (p->v > m) m = p->v;
    return m;
}

