void min_max(const int *a, int n, int *mn, int *mx) {
    *mn = *mx = a[0];
    for (int i = 1; i < n; i++) {
        if (a[i] < *mn) *mn = a[i];
        if (a[i] > *mx) *mx = a[i];
    }
}

exercise.harness:
int main(void) {
    int a[] = {3, -2, 9, 4};
    int lo = 0, hi = 0;
    min_max(a, 4, &lo, &hi);
    CHECK_INT("min", lo, -2);
    CHECK_INT("max", hi, 9);
    int b[] = {7};
    min_max(b, 1, &lo, &hi);
    CHECK("single", lo == 7 && hi == 7);
    return 0;
}

