exercise.solution:
#include <limits.h>

int in_range(long long v) {
    return v >= INT_MIN && v <= INT_MAX;
}

int narrow(long long v, int *out) {
    if (!in_range(v)) return 0;
    *out = (int)v;
    return 1;
}

exercise.harness:
int main(void) {
    int r = 7;
    CHECK_INT("small fits", in_range(5), 1);
    CHECK_INT("INT_MAX fits", in_range(INT_MAX), 1);
    CHECK_INT("INT_MAX + 1 doesn't", in_range((long long)INT_MAX + 1), 0);
    CHECK_INT("INT_MIN fits", in_range(INT_MIN), 1);
    CHECK_INT("narrow fails", narrow(5000000000LL, &r), 0);
    CHECK_INT("out untouched", r, 7);
    CHECK_INT("narrow ok", narrow(-42, &r) && r == -42, 1);
    return 0;
}

