#include <string>
#include <unordered_set>

char first_repeat(const std::string& s) {
    std::unordered_set<char> seen;
    for (char c : s) {
        if (seen.count(c)) return c;
        seen.insert(c);
    }
    return '-';
}

exercise.harness:
int main() {
    CHECK_EQ("swiss", first_repeat("swiss"), 's');
    CHECK_EQ("abca", first_repeat("abca"), 'a');
    CHECK_EQ("abc", first_repeat("abc"), '-');
    CHECK_EQ("abba", first_repeat("abba"), 'b');
}

