}

exercise.solution:
#include <string>
#include <vector>

std::vector<std::string> merge_sorted(const std::vector<std::string>& a, const std::vector<std::string>& b) {
    std::vector<std::string> out;
    out.reserve(a.size() + b.size());
    auto i = a.begin(), j = b.begin();
    while (i != a.end() && j != b.end()) {
        if (*j < *i) out.push_back(*j++);
        else out.push_back(*i++);
    }
    out.insert(out.end(), i, a.end());
    out.insert(out.end(), j, b.end());
    return out;
}

exercise.harness:
int main() {
    CHECK_EQ("merge", merge_sorted({"ancient", "nuke"}, {"dust2", "mirage", "vertigo"}), (std::vector<std::string>{"ancient", "dust2", "mirage", "nuke", "vertigo"}));
    CHECK_EQ("one empty", merge_sorted({}, {"a"}), (std::vector<std::string>{"a"}));
    CHECK_EQ("both empty", merge_sorted({}, {}).size(), 0u);
}

