    struct node *head = NULL;
    for (int v = 1; v <= 3; v++) {
        struct node *n = malloc(sizeof *n);
        if (!n) return 1;
        n->value = v;
        n->next = head;
        head = n;
    }
    for (struct node *p = head; p; p = p->next) printf("%d ", p->value);
    printf("\n");
    while (head) {
        struct node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}

