#include <iostream>
#include <memory>

struct Node {
    int key;
    std::unique_ptr<Node> left, right;
    explicit Node(int k) : key(k) {}
};

void insert(std::unique_ptr<Node> &t, int key) {
    if (!t) t = std::make_unique<Node>(key);
    else if (key < t->key) insert(t->left, key);
    else insert(t->right, key);
}

void in_order(const Node *t) {
    if (!t) return;
    in_order(t->left.get());
    std::cout << t->key << " ";
    in_order(t->right.get());
}

int main() {
    std::unique_ptr<Node> root;
    for (int k : {50, 30, 70, 20, 40}) insert(root, k);
    in_order(root.get());
    std::cout << "\n";
    return 0;
}

#include <iostream>
#include <queue>
#include <vector>

int main() {
    std::vector<std::vector<int>> adj{{1, 2}, {3}, {3}, {4}, {}};
    std::vector<int> dist(adj.size(), -1);
    std::queue<int> q;
    dist[0] = 0;
    q.push(0);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : adj[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
    std::cout << "distance to 4: " << dist[4] << "\n";
    return 0;
}
